<script setup lang="ts">
import { ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import FeatureLayout from '../../components/FeatureLayout.vue'
import AppSheet from '../../components/AppSheet.vue'
import { api } from '../../services/api'
import { config } from '../../config'
import { clearSession,sessionState } from '../../stores/session'
import type { User } from '../../types/domain'
import { errorMessage,requireSession,showMessage } from '../../utils/navigation'
const user=ref<User|null>(sessionState.session?.user||null),error=ref(''),sheet=ref(''),audio=ref(false),notify=ref(false)
async function load(){if(!requireSession())return;error.value='';try{user.value=(await api.home()).user;const prefs=uni.getStorageSync('my-legend:preferences');audio.value=!!prefs?.audio;notify.value=!!prefs?.notify}catch(e){error.value=errorMessage(e)}}
onShow(load)
function savePreferences(){uni.setStorageSync('my-legend:preferences',{audio:audio.value,notify:notify.value})}
function changeAudio(e:unknown){audio.value=!!(e as {detail:{value:boolean}}).detail.value;savePreferences()}
function changeNotify(e:unknown){notify.value=!!(e as {detail:{value:boolean}}).detail.value;savePreferences()}
async function logout(){try{await api.logout()}catch{showMessage('已退出本机登录；后台退出请求未完成')}finally{clearSession();uni.reLaunch({url:'/pages/login/index'})}}
</script>
<template><FeatureLayout title="我的" subtitle="让想象继续，让每一次创作都有归处" active="profile"><view class="page-content"><view class="paper-panel profile-panel"><image :src="user?.avatarUrl||'/static/figma/avatar.png'" class="profile-avatar" mode="aspectFill"/><view><text class="profile-name serif">{{user?.displayName||'正在读取资料'}}</text><text class="small-note">{{config.useMock?'本地体验账号':'我的传说账号'}}</text></view></view><text v-if="error" class="error-copy">{{error}}</text><view class="paper-panel membership-panel section-gap"><view class="row-between"><text class="section-title serif">传说会员</text><text class="pill">VIP</text></view><text class="copy">会员剩余 {{user?.vipDays??'—'}} 天 · 让创作有更多可能</text><button class="warm-button full-button" @tap="sheet='会员权益'">查看会员权益</button></view><view class="paper-panel wallet-panel section-gap"><view><text class="wallet-balance">{{user?.balance??'—'}}</text><text class="small-note">灵感币余额</text></view><button class="outline-button" @tap="sheet='我的订单'">查看订单</button></view><view class="paper-panel profile-links section-gap"><button @tap="sheet='我的订单'">我的订单<text>›</text></button><button @tap="sheet='阅读与语音设置'">阅读与语音设置<text>›</text></button><button @tap="sheet='帮助与关于'">帮助与关于<text>›</text></button></view><button class="outline-button full-button" @tap="logout">退出登录</button></view><AppSheet :title="sheet" :open="!!sheet" @close="sheet=''"><template v-if="sheet==='会员权益'"><text class="section-title serif">让想象不止于此</text><text class="copy">更多故事创作、更多伙伴同行，还有持续更新的阅读与演绎体验。</text><text class="small-note spaced">当前展示权益预览，会员开通与支付尚未开放。</text></template><template v-else-if="sheet==='我的订单'"><text class="section-title serif">还没有正式订单</text><text class="copy muted">会员开通与商品兑换记录，会在接入账号服务后出现在这里。</text></template><template v-else-if="sheet==='阅读与语音设置'"><view class="preference-row"><text>伴读偏好</text><switch :checked="audio" color="#cf502a" @change="changeAudio($event)"/></view><view class="preference-row"><text>消息提醒偏好</text><switch :checked="notify" color="#cf502a" @change="changeNotify($event)"/></view><text class="small-note spaced">偏好保存在本机；实际配音与通知服务尚未开放。</text></template><template v-else><text class="section-title serif">我的传说</text><text class="copy">把灵感写成故事，让故事活起来。</text><text class="small-note spaced">前端原型 v0.2.0 · 本地体验。故事生成、语音、视频和支付服务将逐步接入。</text></template></AppSheet></FeatureLayout></template>
<style scoped>.profile-panel{display:flex;align-items:center;gap:26rpx}.profile-avatar{width:116rpx;height:116rpx;border-radius:50%;border:4rpx solid #e5bd66}.profile-name{display:block;font-size:42rpx;margin-bottom:12rpx}.membership-panel{background:#fff2d4}.membership-panel .section-title{margin:0}.wallet-panel{display:flex;align-items:center;justify-content:space-between}.wallet-balance{font-size:50rpx;font-weight:700;color:#a45d23}.profile-links{padding:0 28rpx}.profile-links button{display:flex;justify-content:space-between;width:100%;padding:28rpx 0;border-bottom:2rpx solid #eadcc9}.profile-links button:last-child{border:0}.preference-row{display:flex;justify-content:space-between;align-items:center;padding:28rpx 0;border-bottom:2rpx solid #eadcc9}</style>
